plugins {
    alias(libs.plugins.kotlin.multiplatform)
    alias(libs.plugins.kotlin.compose)
    alias(libs.plugins.kotlin.serialization)
    alias(libs.plugins.compose.multiplatform)
    alias(libs.plugins.android.library)
}

// The engine bindings are JVM code generated by uniffi; they call the Rust library through JNA,
// which ships as an AAR on Android and a JAR on the desktop. One shared source directory
// (src/jvmShared) holds the app and is compiled into both the Android and desktop targets, each
// with its own JNA artifact, instead of an intermediate source set that would need one JNA for
// both. Generated bindings land in build/engine/kotlin (scripts/build-engine.sh).
val engineKotlin = rootProject.layout.projectDirectory.dir("build/engine/kotlin")

kotlin {
    androidTarget {
        compilerOptions {
            jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
        }
    }
    jvm("desktop") {
        compilerOptions {
            jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
        }
    }

    sourceSets {
        val shared = listOf("src/jvmShared/kotlin", engineKotlin.asFile.path)
        androidMain {
            kotlin.srcDirs(shared)
            dependencies {
                implementation(compose.runtime)
                implementation(compose.foundation)
                implementation(compose.material3)
                implementation(compose.ui)
                implementation(compose.materialIconsExtended)
                implementation("${libs.jna.get()}@aar")
                implementation(libs.kotlinx.serialization.json)
            }
        }
        val desktopMain by getting {
            kotlin.srcDirs(shared)
            // JNA loads the engine from the classpath under its platform folder.
            resources.srcDir(rootProject.layout.projectDirectory.dir("build/engine/desktop"))
            dependencies {
                implementation(compose.runtime)
                implementation(compose.foundation)
                implementation(compose.material3)
                implementation(compose.ui)
                implementation(compose.materialIconsExtended)
                implementation(libs.jna)
                implementation(libs.kotlinx.serialization.json)
                // Skia's native renderer for the OS building the package (each OS packages its own).
                implementation(compose.desktop.currentOs)
            }
        }
        val desktopTest by getting {
            dependencies {
                implementation(kotlin("test"))
            }
        }
    }
}

android {
    namespace = "net.lakesidegames.corporatewarfare.shared"
    // The corridor map, shared with the iPhone app (copied by scripts/build-engine.sh).
    sourceSets["main"].resources.srcDir(rootProject.layout.projectDirectory.dir("build/engine/resources"))
    compileSdk = libs.versions.compileSdk.get().toInt()
    defaultConfig {
        minSdk = libs.versions.minSdk.get().toInt()
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

// Windows and Linux (and, unsigned, macOS) desktop builds of the same app.
compose.desktop {
    application {
        mainClass = "net.lakesidegames.corporatewarfare.MainKt"
        nativeDistributions {
            targetFormats(
                org.jetbrains.compose.desktop.application.dsl.TargetFormat.Msi,
                org.jetbrains.compose.desktop.application.dsl.TargetFormat.Deb,
                org.jetbrains.compose.desktop.application.dsl.TargetFormat.Dmg,
            )
            packageName = "Corporate Warfare"
            packageVersion = "1.3.1"
            vendor = "Lakeside Games"
            linux { packageName = "corporate-warfare" }
            windows {
                menuGroup = "Corporate Warfare"
                upgradeUuid = "5b6f6b2e-3c1d-4b8e-9f1a-0c7d2e4a9b31"
            }
        }
    }
}
